spec.expr:
sum(
  rate(gateway_failed_requests_total{
    job="gateway"
  }[$__rate_interval])
)
/
clamp_min(
  sum(
    rate(gateway_http_requests_total{
      job="gateway"
    }[$__rate_interval])
  ),
  1e-9
)

